files.content:
:root {
  --bg: #1b1b2f;
  --card: #2d2d44;
  --accent: #ffd166;
  --accent-dark: #e0a800;
  --text: #f4f4f8;
  --muted: #a0a0b8;
  --focus: #06d6a0;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background: var(--bg);
  background-image:
    linear-gradient(45deg, rgba(255,255,255,0.02) 25%, transparent 25%, transparent 75%, rgba(255,255,255,0.02) 75%),
    linear-gradient(45deg, rgba(255,255,255,0.02) 25%, transparent 25%, transparent 75%, rgba(255,255,255,0.02) 75%);
  background-size: 16px 16px;
  background-position: 0 0, 8px 8px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  padding: 28px 24px;
  border: 4px solid #000;
  box-shadow: 8px 8px 0 #000, inset 0 0 0 2px rgba(255,255,255,0.06);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.pixel-title {
  margin: 0;
  font-size: 28px;
  letter-spacing: 4px;
  text-align: center;
  color: var(--accent);
  text-shadow: 2px 2px 0 #000;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
  border: 0;
  padding: 0;
  margin: 0;
}

label, legend {
  font-size: 16px;
  font-weight: 700;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

input[type="number"] {
  font: inherit;
  font-size: 18px;
  padding: 12px;
  color: var(--text);
  background: #1b1b2f;
  border: 3px solid #000;
  box-shadow: inset 2px 2px 0 rgba(0,0,0,0.5);
  outline: none;
}

input[type="number"]:focus-visible {
  border-color: var(--focus);
  box-shadow: 0 0 0 3px var(--focus), inset 2px 2px 0 rgba(0,0,0,0.5);
}

.tip-buttons {
  display: flex;
  gap: 10px;
}

.tip-btn {
  flex: 1;
  font: inherit;
  font-size: 18px;
  font-weight: 700;
  padding: 12px 8px;
  cursor: pointer;
  color: var(--text);
  background: #3d3d5c;
  border: 3px solid #000;
  box-shadow: 4px 4px 0 #000;
  transition: transform 0.05s, box-shadow 0.05s, background 0.15s;
}

.tip-btn:hover { background: #4a4a6e; }

.tip-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--focus), 4px 4px 0 #000;
}

.tip-btn:active { transform: translate(2px, 2px); box-shadow: 2px 2px 0 #000; }

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  color: #1b1b2f;
  box-shadow: 4px 4px 0 var(--accent-dark);
}

.results {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px;
  background: #1b1b2f;
  border: 3px solid #000;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
}

.result-label {
  font-size: 16px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.result-value {
  font-size: 22px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.result-value.highlight { color: var(--accent); }

.status {
  margin: 0;
  min-height: 1.2em;
  font-size: 14px;
  color: var(--muted);
  text-align: center;
}

@media (max-width: 380px) {
  .card { padding: 20px 16px; }
  .pixel-title { font-size: 24px; letter-spacing: 2px; }
  .tip-btn { font-size: 16px; padding: 10px 4px; }
  .result-value { font-size: 20px; }
}

(function () {
  'use strict';

  var billInput = document.getElementById('bill');
  var peopleInput = document.getElementById('people');
  var tipOut = document.getElementById('tip-out');
  var totalOut = document.getElementById('total-out');
  var statusEl = document.getElementById('status');
  var tipButtons = Array.prototype.slice.call(document.querySelectorAll('.tip-btn'));

  var selectedTip = null;

  function money(n) {
    return '$' + n.toFixed(2);
  }

  function update() {
    var bill = parseFloat(billInput.value);
    var people = parseInt(peopleInput.value, 10);
    var tipPercent = selectedTip;

    if (isNaN(bill) || bill < 0) bill = 0;
    if (isNaN(people) || people < 1) people = 0;

    if (people === 0) {
      tipOut.textContent = money(0);
      totalOut.textContent = money(0);
      statusEl.textContent = 'Enter at least 1 person.';
      return;
    }

    if (tipPercent === null) {
      tipOut.textContent = money(0);
      totalOut.textContent = money(bill / people);
      statusEl.textContent = 'Choose a tip percent.';
      return;
    }

    var tip = bill * (tipPercent / 100);
    var totalPerPerson = (bill + tip) / people;

    tipOut.textContent = money(tip);
    totalOut.textContent = money(totalPerPerson);
    statusEl.textContent = '';
  }

  tipButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      var value = parseInt(btn.getAttribute('data-tip'), 10);
      selectedTip = value;
      tipButtons.forEach(function (b) {
        b.setAttribute('aria-pressed', b === btn ? 'true' : 'false');
      });
      update();
    });
  });

  billInput.addEventListener('input', update);
  peopleInput.addEventListener('input', update);

  update();
})();
